fn solve(n: i8) -> Vec<char> {
    // Compute the ones digit. Since the problem guarantees 1 <= n <= 999,
    // n is always positive, but we use .abs() to be safe if negatives ever occur.
    let ones = (n % 10).abs();

    // Decide which suffix to use based on the ones digit.
    let suffix = match ones {
        2 | 4 | 5 | 7 | 9 => "hon\n",
        3               => "bon\n",
        _               => "pon\n",
    };

    // Convert the selected &str into a Vec<char> and return it.
    suffix.chars().collect()
}

fn main() {
    // A few quick smoke tests:
    for &n in &[1, 2, 3, 4, 8, 9, 10, 13, 25, 30, 57, 99] {
        let result: String = solve(n).into_iter().collect();
        print!("{} -> {}", n, result);
    }
}